tasks.codeTemplate:
horse_age = 5
if horse_age >= 5:
    print("🎉 The horse is ready for training!")

has_saddle = True
if has_saddle:
    print("🔑 You can mount up!")

gait = "Gallop"
if gait == "Gallop":
    print("🐎 Full speed!")

height = 120
if height <= 100:
    print("⚔️ Easy jump cleared!")
else:
    print("💨 Challenging jump!")

is_raining = False
if is_raining:
    print("🌧️ We'll ride in the indoor arena.")
else:
    print("☀️ Perfect for the pasture!")

experience = 750
if experience >= 1000:
    print("🏆 Master Rider!")
elif experience >= 500:
    print("⭐ Advanced Rider!")
elif experience >= 100:
    print("🌟 Beginner!")
else:
    print("📚 Still a lot to practise...")

discipline = "Jumping"
if discipline == "Dressage":
    print("🎆 Elegant dressage!")
elif discipline == "Jumping":
    print("🏇 Show jumping course!")
else:
    print("❓ Unknown discipline!")

stable_door_locked = True
right_key = True

if stable_door_locked:
    print("🚪 The stable door is locked.")
    if right_key:
        print("🔑 The key fits – the stable door opens!")
    else:
        print("❌ This key does not fit.")
else:
    print("🚪 The stable door is already open.")

name = "Thunder"
if name = "Thunder":
    print("Hello Thunder!")

age = 8
if age >= 5:
    print("Trained")
elif:
    print("In training")
